16: function dependentsOf(project: Project, sectionId: string): Set<string> {
17:   const affected = new Set<string>();
18:   let changed = true;
19:   while (changed) {
20:     changed = false;
21:     for (const section of project.sections) {
22:       if (!affected.has(section.id) && section.dependencies.some((id) => id === sectionId || affected.has(id))) {
23:         affected.add(section.id);
24:         changed = true;
