31: export function reviseSection(project: Project, sectionId: string, content: string): Project {
32:   const next = clone(project);
33:   const section = next.sections.find((item) => item.id === sectionId);
34:   if (!section) throw new WorkflowConflict(`Unknown section: ${sectionId}`);
35:   const hash = contentHash(content);
36:   if (section.hash === hash && section.version > 0) return next;
37: 
38:   section.content = content;
39:   section.hash = hash;
40:   section.version += 1;
41:   section.status = "DRAFT";
42: 
43:   const affected = dependentsOf(next, sectionId);
44:   for (const dependent of next.sections) {
45:     if (affected.has(dependent.id) && dependent.status === "APPROVED") dependent.status = "STALE";
46:   }
47:   for (const approval of next.approvals) {
48:     if ((approval.sectionId === sectionId || affected.has(approval.sectionId)) && approval.staleReason === null) {
49:       approval.staleReason = `${section.title} changed`;
50:     }
51:   }
52:   return projectSchema.parse(refreshNextAction(next));
53: }
