199: function syncAssumptionMemory(
200:   project: Project,
201:   assumptions: Project["oracleIntake"]["assumptions"],
202:   sourceId: string,
203:   createdAt: string,
204: ): void {
205:   const activeIds = new Set(assumptions.map((assumption) => assumption.id));
206:   const bucket = project.memory.assumptions ??= [];
207:   for (const entry of bucket) {
208:     if (entry.sourceId?.startsWith("assumption:") && !activeIds.has(entry.sourceId.slice("assumption:".length))) {
209:       entry.status = "SUPERSEDED";
210:     }
211:   }
212:   for (const assumption of assumptions) {
213:     const existing = bucket.find((entry) => entry.sourceId === `assumption:${assumption.id}` && entry.status !== "SUPERSEDED");
214:     if (existing?.text === assumption.statement) continue;
215:     if (existing) existing.status = "SUPERSEDED";
216:     bucket.push({
217:       id: randomUUID(),
