230: function syncTextMemory(
231:   project: Project,
232:   bucketName: "facts" | "decisions" | "constraints" | "risks",
233:   texts: string[],
234:   source: "user" | "oracle",
235:   sourceId: string,
236:   createdAt: string,
237: ): void {
238:   const bucket = project.memory[bucketName];
