277: export function grantMakerScope(project: Project, statement: string): Project {
278:   const next = clone(project);
279:   const unresolved = next.sections.filter((section) => section.status !== "APPROVED");
280:   if (unresolved.length) throw new WorkflowConflict("Maker scope waits until every current section is approved.");
281:   if (next.product.status !== "APPROVED") throw new WorkflowConflict("Maker scope waits for an approved product.");
282:   next.makerScope = { status: "GRANTED", statement };
283:   rememberTranscript(next, "user", `Granted Maker scope: ${statement}`);
284:   return projectSchema.parse(refreshNextAction(next));
285: }
