293:   next.witnessDrafts = drafts.map((draft) => ({
294:     id: randomUUID(),
295:     title: draft.title,
296:     content: draft.content,
297:     nativeSessionId: sessionId,
298:     createdAt: new Date().toISOString(),
299:   }));
300:   rememberSession(next, "witness", sessionId);
301:   rememberTranscript(next, "witness", drafts.map((draft) => draft.title).join(", "));
302:   return projectSchema.parse(refreshNextAction(next));
303: }
