306: export function compileApprovedPlan(project: Project): string {
307:   const unresolved = project.sections.filter((section) => section.status !== "APPROVED");
308:   if (unresolved.length) throw new WorkflowConflict(`Plan has ${unresolved.length} unresolved section(s).`);
309:   return project.sections
310:     .toSorted((left, right) => left.order - right.order)
311:     .map((section) => `## ${section.title}\n\n${section.content}`)
312:     .join("\n\n");
313: }

