318: /** Applies a validated reply. Used for live completion and late reconciliation. */
319: export function applyValidatedReply(
320:   project: Project,
321:   operationId: string,
322:   reply: ValidatedReply,
323:   context: ReplyApplyContext,
324: ): Project {
325:   const operation = project.operations.find((item) => item.id === operationId);
326:   if (!operation || operation.appliedAt) {
327:     // A recovered or repeated application must never double-write.
328:     return refreshNextAction(structuredClone(project));
329:   }
330:   const now = new Date().toISOString();
331:   let resultText = "Validated reply applied.";
332:   let next: Project;
333:   if (reply.intent === "clarify") {
334:     assertOracleReplyReady(project, operation, reply.reply);
335:     next = recordOracleProposal(structuredClone(project), {
336:       mode: reply.reply.mode,
337:       questions: reply.reply.questions.map((question) => ({
338:         ...question,
339:         prompt: context.redact(question.prompt),
340:         whyItMatters: context.redact(question.whyItMatters),
341:         suggestedChoices: question.suggestedChoices.map(context.redact),
342:       })),
343:       assumptions: reply.reply.assumptions.map((assumption) => ({
344:         ...assumption,
345:         statement: context.redact(assumption.statement),
346:         reason: context.redact(assumption.reason),
347:       })),
348:       knownConstraints: reply.reply.knownConstraints.map(context.redact),
349:       intake: Object.fromEntries(Object.entries(reply.reply.intake).map(([field, answer]) => [
350:         field,
351:         answer
352:           ? {
353:               ...answer,
354:               value: Array.isArray(answer.value)
355:                 ? answer.value.map(context.redact)
356:                 : context.redact(answer.value),
357:             }
358:           : null,
359:       ])) as typeof reply.reply.intake,
360:       proposal: reply.reply.proposal
361:         ? {
362:             ...reply.reply.proposal,
363:             title: context.redact(reply.reply.proposal.title),
364:             summary: context.redact(reply.reply.proposal.summary),
365:             intendedUser: context.redact(reply.reply.proposal.intendedUser),
366:             problem: context.redact(reply.reply.proposal.problem),
367:             desiredOutcome: context.redact(reply.reply.proposal.desiredOutcome),
368:             mustHaveFeatures: reply.reply.proposal.mustHaveFeatures.map(context.redact),
369:             optionalFeatures: reply.reply.proposal.optionalFeatures.map(context.redact),
370:             nonGoals: reply.reply.proposal.nonGoals.map(context.redact),
371:             successCriteria: reply.reply.proposal.successCriteria.map(context.redact),
372:             facts: reply.reply.proposal.facts.map(context.redact),
373:             userDecisions: reply.reply.proposal.userDecisions.map(context.redact),
374:             assumptions: reply.reply.proposal.assumptions.map(context.redact),
375:           }
376:         : null,
377:       unresolvedRisks: reply.reply.unresolvedRisks.map(context.redact),
378:       recommendedNextAction: context.redact(reply.reply.recommendedNextAction),
379:       sessionId: context.sessionId,
380:     });
381:     resultText = reply.reply.mode === "proposal"
382:       ? "Oracle proposal stored. It is not approved."
383:       : `Oracle saved the intake and asked ${reply.reply.questions.length} focused question(s).`;
384:   } else if (reply.intent === "draft") {
385:     if (!operation.sectionId) throw new Error("A recovered draft names its target section.");
386:     const content = context.redact(formatSectionDraft(reply.reply));
387:     const revised = reviseSection(structuredClone(project), operation.sectionId, content);
388:     rememberSession(revised, "architect", context.sessionId);
389:     rememberTranscript(revised, "architect", content);
390:     next = revised;
391:     resultText = "Draft stored as the current section version.";
392:   } else {
393:     next = recordWitnessDrafts(structuredClone(project), [
394:       { title: "Findings", content: context.redact(reply.reply.findings) },
395:       { title: "Limitations", content: context.redact(reply.reply.limitations) },
396:       { title: "Draft notes", content: context.redact(reply.reply.draftNotes) },
397:     ], context.sessionId);
398:     resultText = "Witness drafts stored from a fresh session.";
399:   }
400:   const finalOperation = next.operations.find((item) => item.id === operationId);
401:   if (finalOperation && !finalOperation.appliedAt) {
402:     finalOperation.status = "SUCCEEDED";
403:     finalOperation.finishedAt ??= now;
404:     finalOperation.appliedAt = now;
405:     finalOperation.lastObservedAt = now;
406:     finalOperation.statusReason = null;
407:     finalOperation.providerError = null;
408:     finalOperation.progress = null;
409:     finalOperation.nativeMessageId = context.messageId ?? finalOperation.nativeMessageId;
410:     finalOperation.result = resultText;
411:   }
412:   return refreshNextAction(next);
413: }
