415: function assertOracleReplyReady(
416:   project: Project,
417:   operation: Operation,
418:   reply: z.infer<typeof oracleReplySchema>,
419: ): void {
420:   if (reply.mode !== "proposal") return;
421:   const essential = [
422:     ["intendedUser", reply.intake.intendedUser],
423:     ["problem", reply.intake.problem],
424:     ["desiredOutcome", reply.intake.desiredOutcome],
425:     ["mustHaveFeatures", reply.intake.mustHaveFeatures?.value.length ? reply.intake.mustHaveFeatures : null],
426:   ] as const;
427:   const missing: string[] = essential.filter(([, answer]) => !answer).map(([field]) => field);
428:   if (project.source.status !== "CONFIRMED") missing.unshift("projectSource");
429:   if (missing.length) {
430:     throw new Error(`The Oracle proposed before required intake was consolidated: ${missing.join(", ")}.`);
431:   }
432:   const assumedEssential = essential
433:     .filter(([, answer]) => answer?.source === "ASSUMPTION")
434:     .map(([field]) => field);
435:   if (!assumedEssential.length) return;
436:   if (!operation.oracleProceedWithAssumptions) {
437:     throw new Error(`The Oracle proposed too early; explicit assumption permission is required for: ${assumedEssential.join(", ")}.`);
438:   }
439:   const assumed = new Set(reply.assumptions.map((assumption) => assumption.field));
440:   const uncovered = assumedEssential.filter((field) => !assumed.has(field));
441:   if (uncovered.length) {
442:     throw new Error(`The Oracle did not state assumptions for missing intake fields: ${uncovered.join(", ")}.`);
443:   }
444: }
