446: /**
447:  * Validates a reply for the expected output type. The same schemas and prose
448:  * fallbacks are used for live replies and late reconciliation, so a response
449:  * can never bypass validation.
450:  */
451: export function validateReply(
452:   intent: "clarify" | "draft" | "witness" | "question",
453:   text: string,
454:   redact: (value: string) => string,
455: ): ValidatedReply | { ok: false; resultText: string } {
456:   if (intent === "draft") {
457:     try {
458:       return { ok: true, intent: "draft", reply: sectionReplySchema.parse(extractJsonObject(text)) };
459:     } catch {
460:       const prose = text.trim();
461:       if (prose.length < 80) {
462:         return { ok: false, resultText: `The Architect reply was malformed, so the section was left unchanged. Reply began: ${redact(prose.slice(0, 240))}` };
463:       }
464:       return {
465:         ok: true,
466:         intent: "draft",
467:         reply: {
468:           content: prose.slice(0, 12_000),
469:           recommendation: "The Architect returned prose. Review the draft before approval.",
470:           tradeoff: "Separate recommendation and tradeoff fields were not returned.",
471:         },
472:       };
473:     }
474:   }
475:   if (intent === "witness") {
476:     try {
477:       return { ok: true, intent: "witness", reply: witnessReplySchema.parse(extractJsonObject(text)) };
478:     } catch {
479:       const prose = text.trim();
480:       if (prose.length < 80) {
481:         return { ok: false, resultText: `The Witness reply was malformed, so no draft was stored. Reply began: ${redact(prose.slice(0, 240))}` };
482:       }
483:       return {
484:         ok: true,
485:         intent: "witness",
486:         reply: {
487:           findings: prose.slice(0, 8_000),
488:           limitations: "The Witness returned prose rather than separate fields.",
489:           draftNotes: "These notes are an in-app review. They are not a submitted article or video.",
490:         },
491:       };
492:     }
493:   }
494:   try {
495:     return { ok: true, intent: "clarify", reply: oracleReplySchema.parse(extractJsonObject(text)) };
496:   } catch {
497:     return { ok: false, resultText: "The Oracle reply was malformed, so no proposal was stored." };
498:   }
499: }

