403: function ProjectSourceOnboarding(props: {
404:   project: WorkshopProject;
405:   busy: boolean;
406:   act: (work: () => Promise<{ project: WorkshopProject }>) => Promise<void>;
407: }) {
408:   const [kind, setKind] = useState<"NEW_PROJECT" | "LOCAL_REPOSITORY" | "REMOTE_REPOSITORY" | "SAVED_PROJECT">("NEW_PROJECT");
409:   const [value, setValue] = useState("");
410:   const [replacePending, setReplacePending] = useState(false);
411: 
412:   if (props.project.source.status === "PENDING_CONFIRMATION" && !replacePending) {
413:     return (
414:       <section className="stage-panel source-onboarding" aria-labelledby="source-confirm-title">
415:         <div className="panel-intro">
416:           <span className="panel-icon"><ScrollText size={18} aria-hidden="true" /></span>
417:           <div>
418:             <p className="eyebrow">Project source · confirmation</p>
419:             <h1 id="source-confirm-title">Confirm the managed import workspace</h1>
420:             <p>The URL passed validation and contains no embedded credentials. The repository has not been imported and no agent has write access yet.</p>
421:           </div>
422:         </div>
423:         <div className="reading prose proposal-card">
424:           <h2>{props.project.source.label ?? "Remote repository"}</h2>
425:           <p>{props.project.source.repositoryUrl}</p>
426:           <p className="meta">The import stays inside the app-managed data directory. Confirmation permits the import; it does not approve a product, grant Maker write access, or start a run.</p>
427:         </div>
428:         <div className="actions">
429:           <button className="action" type="button" disabled={props.busy} onClick={() => void props.act(() => confirmRemoteSource(props.project))}>
430:             Confirm and import
431:           </button>
432:           <button className="action secondary" type="button" disabled={props.busy} onClick={() => setReplacePending(true)}>
433:             Choose a different source
434:           </button>
435:         </div>
436:       </section>
437:     );
438:   }
439: 
440:   const choices = [
441:     ["NEW_PROJECT", "New project", "Start discovery without an existing repository."],
442:     ["LOCAL_REPOSITORY", "Existing local repository", "Validate an existing directory with the workspace security policy."],
443:     ["REMOTE_REPOSITORY", "Remote repository URL", "Validate a credential-free HTTPS URL, then import only after confirmation."],
444:     ["SAVED_PROJECT", "Continue saved project", "Resume the project state already stored by this installation."],
445:   ] as const;
446:   const needsValue = kind === "LOCAL_REPOSITORY" || kind === "REMOTE_REPOSITORY";
447:   const submit = () => {
448:     if (kind === "LOCAL_REPOSITORY") return props.act(() => selectProjectSource(props.project, { kind, path: value.trim() }));
449:     if (kind === "REMOTE_REPOSITORY") return props.act(() => selectProjectSource(props.project, { kind, url: value.trim() }));
450:     if (kind === "SAVED_PROJECT") return props.act(() => selectProjectSource(props.project, { kind }));
451:     return props.act(() => selectProjectSource(props.project, { kind, label: value.trim() || null }));
452:   };
453: 
454:   return (
455:     <section className="stage-panel source-onboarding" aria-labelledby="source-title">
456:       <div className="panel-intro">
457:         <span className="panel-icon"><Sparkles size={18} aria-hidden="true" /></span>
458:         <div>
459:           <p className="eyebrow">Project source · step 1</p>
460:           <h1 id="source-title">Where is this project starting?</h1>
461:           <p>The Oracle uses this choice to ask relevant discovery questions. Choosing a source never approves a product or starts implementation.</p>
462:         </div>
463:       </div>
464:       <fieldset className="source-choice-grid">
465:         <legend className="sr-only">Choose a project source</legend>
466:         {choices.map(([id, label, description]) => (
467:           <label className={`source-choice ${kind === id ? "selected" : ""}`} key={id}>
468:             <input type="radio" name="project-source" value={id} checked={kind === id} onChange={() => { setKind(id); setValue(""); }} />
469:             <span><strong>{label}</strong><small>{description}</small></span>
470:           </label>
471:         ))}
472:       </fieldset>
473:       {kind === "LOCAL_REPOSITORY" ? (
474:         <label>Local repository path<input value={value} onChange={(event) => setValue(event.target.value)} placeholder="/path/to/repository" /></label>
475:       ) : kind === "REMOTE_REPOSITORY" ? (
476:         <label>Remote repository URL<input value={value} onChange={(event) => setValue(event.target.value)} placeholder="https://github.com/owner/repository.git" /></label>
477:       ) : kind === "NEW_PROJECT" ? (
478:         <label>Working name <span className="meta">optional</span><input value={value} onChange={(event) => setValue(event.target.value)} placeholder="Untitled project" /></label>
479:       ) : null}
480:       <div className="actions">
481:         <button className="action" type="button" disabled={props.busy || (needsValue && !value.trim())} onClick={() => void submit()}>
482:           Continue to discovery
483:         </button>
484:       </div>
485:     </section>
486:   );
487: }
