518: function WorkshopHeader({ connection, onSetup }: { connection: ConnectionStatus | null; onSetup: () => void }) {
519:   const state = connection?.state;
520:   const live = state === "connected";
521:   const warn = state === "degraded" || state === "checking";
522:   return (
523:     <header className="workshop-header">
524:       <div className="workshop-header-inner">
525:         <Brand compact />
526:         <div className="workshop-header-actions">
527:           <a href="/">Overview</a>
528:           <a href="/demo">Demo</a>
529:           <button className="engine-pill" type="button" onClick={onSetup} aria-label="Open OpenCode connection setup">
530:             <span className={live ? "engine-dot is-live" : warn ? "engine-dot is-warn" : "engine-dot"} aria-hidden="true" />
531:             {connection ? connectionLabel(state) : "Checking OpenCode"}
532:           </button>
533:         </div>
534:       </div>
535:     </header>
536:   );
537: }
