539: function connectionLabel(state: ConnectionStatus["state"] | undefined): string {
540:   if (!state) return "Checking OpenCode";
541:   if (state === "connected") return "OpenCode connected";
542:   if (state === "degraded") return "OpenCode warnings";
543:   if (state === "authentication_required") return "OpenCode auth required";
544:   if (state === "incompatible_version") return "OpenCode incompatible";
545:   if (state === "not_configured") return "OpenCode not configured";
546:   if (state === "checking") return "Checking OpenCode";
547:   return "OpenCode unreachable";
548: }
