554: function OraclePanel(props: {
555:   project: WorkshopProject;
556:   text: string;
557:   setText: (value: string) => void;
558:   busy: boolean;
559:   act: (work: () => Promise<{ project: WorkshopProject }>) => Promise<void>;
560: }) {
561:   const proposal = props.project.product.proposal;
562:   const structured = props.project.product.structuredProposal;
563:   const questions = props.project.oracleIntake.unresolvedQuestions;
564:   const activeAnswers = (props.project.memory.answers ?? []).filter((entry) => entry.status !== "SUPERSEDED");
565:   const activeAssumptions = (props.project.memory.assumptions ?? []).filter((entry) => entry.status !== "SUPERSEDED");
566:   return (
567:     <section className="stage-panel" aria-labelledby="oracle-panel-title">
568:       <div className="panel-intro">
569:         <span className="panel-icon"><Sparkles size={18} aria-hidden="true" /></span>
570:         <div>
571:           <h2 id="oracle-panel-title">Oracle: guided project discovery</h2>
572:           <p>Answer a few focused questions at a time. The Oracle saves facts, decisions, and assumptions separately before proposing a product.</p>
573:         </div>
574:       </div>
575:       {proposal ? (
576:         <div className="reading prose proposal-card">
577:           <div className="proposal-head"><h3>{structured?.title ?? "Oracle proposal"}</h3><StatusChip status={props.project.product.status} /></div>
578:           <p>{structured?.summary ?? proposal}</p>
579:           {structured ? (
580:             <div className="proposal-evidence-grid">
581:               <div><h4>Facts</h4>{structured.facts.length ? <ul>{structured.facts.map((item) => <li key={item}>{item}</li>)}</ul> : <p className="meta">None recorded.</p>}</div>
582:               <div><h4>User decisions</h4>{structured.userDecisions.length ? <ul>{structured.userDecisions.map((item) => <li key={item}>{item}</li>)}</ul> : <p className="meta">None recorded.</p>}</div>
583:               <div><h4>Assumptions</h4>{structured.assumptions.length ? <ul>{structured.assumptions.map((item) => <li key={item}>{item}</li>)}</ul> : <p className="meta">None.</p>}</div>
584:             </div>
585:           ) : null}
586:         </div>
587:       ) : questions.length ? (
588:         <div className="oracle-questions" aria-label="Oracle questions">
589:           {questions.map((question, index) => (
590:             <article className="reading proposal-card" key={question.id}>
591:               <p className="eyebrow">Question {index + 1} · {question.field}</p>
592:               <h3>{question.prompt}</h3>
593:               <p>{question.whyItMatters}</p>
594:               {question.suggestedChoices.length ? <p className="meta">Suggested choices: {question.suggestedChoices.join(" · ")}</p> : null}
595:             </article>
596:           ))}
597:         </div>
598:       ) : (
599:         <EmptyState title="Discovery is ready">Tell the Oracle what you want to build. It will ask only the highest-value follow-ups before proposing scope.</EmptyState>
600:       )}
601:       {(activeAnswers.length || activeAssumptions.length) ? (
602:         <details className="memory-card">
603:           <summary>Project memory · {activeAnswers.length} answers · {activeAssumptions.length} assumptions</summary>
604:           {activeAnswers.length ? <div><h4>Recorded answers</h4><ul>{activeAnswers.map((entry) => <li key={entry.id}><strong>{entry.field ?? "answer"}:</strong> {entry.text}</li>)}</ul></div> : null}
605:           {activeAssumptions.length ? <div><h4>Stated assumptions</h4><ul>{activeAssumptions.map((entry) => <li key={entry.id}><strong>{entry.field ?? "assumption"}:</strong> {entry.text}</li>)}</ul></div> : null}
606:         </details>
607:       ) : null}
608:       <label htmlFor="oracle-text">{proposal ? "Correction or follow-up" : questions.length ? "Your answers or corrections" : "Project goal"}</label>
609:       <textarea id="oracle-text" value={props.text} onChange={(event) => props.setText(event.target.value)} maxLength={8000} />
610:       <div className="actions">
611:         {proposal ? (
612:           <button className="action" type="button" disabled={props.busy} onClick={() => void props.act(() => approveProduct(props.project))}>
613:             Approve product
614:           </button>
615:         ) : (
616:           <button className="action" type="button" disabled={props.busy || props.text.trim().length < 1} onClick={() => void props.act(() => sendMessage(props.project, "clarify", props.text))}>
617:             {questions.length ? "Save answers" : "Begin discovery"}
618:           </button>
619:         )}
620:         {proposal ? (
621:           <button className="action secondary" type="button" disabled={props.busy || props.text.trim().length < 1} onClick={() => void props.act(() => sendMessage(props.project, "question", props.text))}>
622:             Ask a question
623:           </button>
624:         ) : null}
625:         {!proposal && props.text.trim().length > 0 ? (
626:           <button className="action secondary" type="button" disabled={props.busy} onClick={() => void props.act(() => sendMessage(props.project, "clarify", props.text, true))}>
627:             Proceed with stated assumptions
628:           </button>
629:         ) : null}
630:         {proposal && props.text.trim().length > 0 ? (
631:           <button className="action secondary" type="button" disabled={props.busy} onClick={() => void props.act(() => sendMessage(props.project, "clarify", props.text))}>
632:             Correct an answer
633:           </button>
634:         ) : null}
635:       </div>
636:     </section>
637:   );
638: }
