842: function spiritStateFor(
843:   project: WorkshopProject,
844:   section: WorkshopProject["sections"][number] | null,
845: ): SpiritState {
846:   if (project.stage === "ORACLE") {
847:     return project.product.status === "PROPOSED" ? "clarification" : "listening";
