849:   if (project.stage === "ARCHITECT") {
850:     return section && (section.status === "DRAFT" || section.status === "STALE") ? "drawing" : "approval";
851:   }
852:   if (project.stage === "MAKER") {
853:     const latest = [...project.operations].reverse().find((operation) => operation.kind === "maker");
854:     if (!latest) return "idle";
855:     if (latest.status === "WAITING_PERMISSION") return "permission";
856:     if (latest.status === "ABANDONED" || latest.status === "COMPLETED_UNAPPLIED") return "permission";
857:     if (latest.status === "FAILED" || latest.status === "CANCELLED") return "blocked";
858:     if (latest.status === "SUCCEEDED") return "success";
859:     return "building";
860:   }
861:   if (project.evidence.some((item) => item.result === "FAIL" || item.result === "INCONCLUSIVE")) return "warning";
862:   if (project.witnessDrafts.length > 0) return "evidence";
863:   return "scanning";
864: }

