168: let sessionToken: string | null = null;
169: let sessionUnavailable = false;
170: 
171: /**
172:  * The hosted demo deliberately issues no session token. A failed token request
173:  * is not fatal for read-only requests; the server returns DEMO_READ_ONLY for
174:  * mutations before looking at the token.
175:  */
176: async function token(): Promise<string | null> {
177:   if (sessionToken) return sessionToken;
178:   if (sessionUnavailable) return null;
179:   try {
180:     const response = await fetch("/api/session");
181:     if (!response.ok) {
182:       sessionUnavailable = true;
183:       return null;
184:     }
185:     const body = await response.json() as { token: string };
186:     sessionToken = REDACTED;
187:     return sessionToken;
188:   } catch {
189:     sessionUnavailable = true;
190:     return null;
191:   }
192: }
