194: async function request<T>(path: string, init?: { method?: string; body?: unknown }): Promise<T> {
195:   const headers: Record<string, string> = {};
196:   const currentToken = await token();
197:   if (currentToken) headers["x-ub-session-token"] = currentToken;
198:   if (init?.body !== undefined) {
199:     headers["content-type"] = "application/json";
200:   }
201:   const response = await fetch(path, {
202:     method: init?.method ?? "GET",
203:     headers,
204:     body: init?.body !== undefined ? JSON.stringify(init.body) : undefined,
205:   });
206:   const body = await response.json() as T & {
207:     message?: string;
208:     code?: string;
209:     retryable?: boolean;
210:     providerError?: ProviderErrorDetails | null;
211:     requestId?: string;
212:   };
213:   if (!response.ok) {
214:     throw new ApiError(
215:       body.message ?? "The workshop could not complete that action.",
216:       body.code ?? "REQUEST_FAILED",
217:       Boolean(body.retryable),
218:       body.providerError ?? null,
219:       body.requestId ?? null,
220:     );
221:   }
222:   return body;
223: }
