export function httpSecurityFromConfig(config: AppConfig): HttpSecurityOptions {
  return {
    mode: config.mode,
    allowedHosts: config.allowedHosts,
    allowedOrigins: config.allowedOrigins,
    trustProxy: config.trustProxy,
