import { Fragment, type ReactNode } from "react";
import {
  parseMarkdown,
  safeHref,
  type MarkdownBlock,
  type MarkdownInline,
} from "../../shared/markdown.ts";

function inline(nodes: MarkdownInline[], keyPrefix = "i"): ReactNode[] {
  return nodes.map((node, index) => {
    const key = `${keyPrefix}-${index}`;
    if (node.type === "text") return <Fragment key={key}>{node.value}</Fragment>;
    if (node.type === "break") return <br key={key} />;
    if (node.type === "code") return <code key={key}>{node.value}</code>;
    if (node.type === "strong") return <strong key={key}>{inline(node.children, key)}</strong>;
    if (node.type === "em") return <em key={key}>{inline(node.children, key)}</em>;
    if (node.type === "strike") return <del key={key}>{inline(node.children, key)}</del>;
    if (node.type === "link") {
      const href = safeHref(node.href);
      return href
        ? <a key={key} href={href} target="_blank" rel="noreferrer noopener">{inline(node.children, key)}</a>
        : <span key={key}>{inline(node.children, key)}</span>;
    }
    return null;
  });
}

function listItems(
  items: Array<{ depth: number; text: string; children: MarkdownInline[] }>,
  ordered: boolean,
  keyPrefix: string,
): ReactNode {
  const render = (start: number, depth: number, prefix: string): { nodes: ReactNode[]; next: number } => {
    const nodes: ReactNode[] = [];
    let index = start;
    while (index < items.length) {
      const item = items[index];
      if (item.depth < depth) break;
      if (item.depth > depth) {
        const nested = render(index, item.depth, `${prefix}-n${index}`);
        nodes.push(nested.nodes);
        index = nested.next;
        continue;
      }
      const children: ReactNode[] = [<Fragment key={`${prefix}-t${index}`}>{inline(item.children, `${prefix}-${index}`)}</Fragment>];
      let next = index + 1;
      if (next < items.length && items[next].depth > depth) {
        const nested = render(next, items[next].depth, `${prefix}-n${index}`);
        children.push(nested.nodes);
        next = nested.next;
      }
      nodes.push(<li key={`${prefix}-${index}`}>{children}</li>);
      index = next;
    }
    return {
      nodes: ordered ? <ol key={prefix}>{nodes}</ol> : <ul key={prefix}>{nodes}</ul>,
      next: index,
    };
  };
  return render(0, items[0]?.depth ?? 0, keyPrefix).nodes;
}

function renderBlock(block: MarkdownBlock, index: number): ReactNode {
  const key = `b-${index}`;
  if (block.type === "heading") {
    const Tag = `h${Math.min(6, Math.max(1, block.level))}` as "h1" | "h2" | "h3" | "h4" | "h5" | "h6";
    return <Tag key={key}>{inline(block.children, key)}</Tag>;
  }
  if (block.type === "paragraph") return <p key={key}>{inline(block.children, key)}</p>;
  if (block.type === "list") return <Fragment key={key}>{listItems(block.items, block.ordered, key)}</Fragment>;
  if (block.type === "code") {
    const language = block.language?.replace(/[^A-Za-z0-9_+-]/g, "") || undefined;
    return (
      <pre key={key} className="markdown-code">
        <code className={language ? `language-${language}` : undefined}>{block.code}</code>
      </pre>
    );
  }
  if (block.type === "table") {
    return (
      <div key={key} className="markdown-table-wrap">
        <table>
          <thead>
            <tr>{block.header.map((cell, cellIndex) => <th key={`${key}-h${cellIndex}`}>{cell}</th>)}</tr>
          </thead>
          <tbody>
            {block.rows.map((row, rowIndex) => (
              <tr key={`${key}-r${rowIndex}`}>
                {block.header.map((_cell, cellIndex) => <td key={`${key}-r${rowIndex}-c${cellIndex}`}>{row[cellIndex] ?? ""}</td>)}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    );
  }
  if (block.type === "blockquote") return <blockquote key={key}>{inline(block.children, key)}</blockquote>;
  if (block.type === "hr") return <hr key={key} />;
  return null;
}

/**
 * Safe Markdown renderer. No block is ever interpreted as HTML and links are
 * filtered through safeHref, so generated content cannot execute script.
 */
export function Markdown({ content, className = "" }: { content: string; className?: string }) {
  const blocks = parseMarkdown(content);
  if (!blocks.length) return null;
  return <div className={`markdown ${className}`.trim()}>{blocks.map(renderBlock)}</div>;
}

import { useEffect, useMemo, useState } from "react";
import {
  buildSideBySideRows,
  buildUnifiedHunks,
  computeLineDiff,
  summarizeDiff,
} from "../../shared/diff.ts";

export type DiffView = "unified" | "side-by-side";

function defaultView(): DiffView {
  if (typeof window === "undefined") return "unified";
  return window.matchMedia("(min-width: 900px)").matches ? "side-by-side" : "unified";
}

/**
 * Review surface for one proposed section revision. The default view follows
 * the available width; both views are always available through the toggle.
 */
export function RevisionDiff({
  before,
  after,
  view,
  onViewChange,
}: {
  before: string;
  after: string;
  view?: DiffView;
  onViewChange?: (view: DiffView) => void;
}) {
  const [localView, setLocalView] = useState<DiffView>(() => defaultView());
  const selected = view ?? localView;
  const lines = useMemo(() => computeLineDiff(before, after), [before, after]);
  const hunks = useMemo(() => buildUnifiedHunks(lines), [lines]);
  const rows = useMemo(() => buildSideBySideRows(hunks), [hunks]);
  const stats = useMemo(() => summarizeDiff(lines), [lines]);

  useEffect(() => {
    if (view !== undefined) return;
    const query = window.matchMedia("(min-width: 900px)");
    const listener = () => setLocalView(query.matches ? "side-by-side" : "unified");
    query.addEventListener("change", listener);
    return () => query.removeEventListener("change", listener);
  }, [view]);

  const choose = (next: DiffView) => {
    if (onViewChange) onViewChange(next);
    else setLocalView(next);
  };

  return (
    <div className="revision-diff">
      <div className="diff-toolbar">
        <div className="diff-stats" aria-label="Diff summary">
          <span className="diff-added">+{stats.added}</span>
          <span className="diff-removed">−{stats.removed}</span>
          <span className="meta">{stats.unchanged} unchanged</span>
        </div>
        <div className="diff-toggle" role="group" aria-label="Diff layout">
          <button type="button" className={selected === "unified" ? "is-active" : ""} aria-pressed={selected === "unified"} onClick={() => choose("unified")}>Unified</button>
          <button type="button" className={selected === "side-by-side" ? "is-active" : ""} aria-pressed={selected === "side-by-side"} onClick={() => choose("side-by-side")}>Side by side</button>
        </div>
      </div>
      {hunks.length === 0 ? (
        <p className="meta">The proposed revision is identical to the current draft.</p>
      ) : selected === "unified" ? (
        <div className="diff-unified" role="table" aria-label="Unified diff">
          {hunks.map((hunk, hunkIndex) => (
            <div className="diff-hunk" key={`hunk-${hunkIndex}`} role="rowgroup">
              <div className="diff-hunk-head" role="row">
                <span>@@ -{hunk.oldStart},{hunk.oldCount} +{hunk.newStart},{hunk.newCount} @@</span>
              </div>
              {hunk.lines.map((line, lineIndex) => (
                <div className={`diff-line ${line.type}`} key={`line-${hunkIndex}-${lineIndex}`} role="row">
                  <span className="diff-gutter" aria-hidden="true">{line.oldLine ?? ""}</span>
                  <span className="diff-gutter" aria-hidden="true">{line.newLine ?? ""}</span>
                  <span className="diff-sign" aria-hidden="true">{line.type === "added" ? "+" : line.type === "removed" ? "−" : " "}</span>
                  <span className="diff-text">{line.text || " "}</span>
                </div>
              ))}
            </div>
          ))}
        </div>
      ) : (
        <div className="diff-side-by-side" role="table" aria-label="Side-by-side diff">
          <div className="diff-column-head" role="row">
            <span>Current draft</span>
            <span>Proposed revision</span>
          </div>
          {rows.map((row, index) => (
            <div className={`diff-pair ${row.type}`} key={`pair-${index}`} role="row">
              <div className={`diff-cell old ${row.oldText === null ? "empty" : ""}`} role="cell">
                <span className="diff-gutter" aria-hidden="true">{row.oldLine ?? ""}</span>
                <span className="diff-text">{row.oldText ?? ""}</span>
              </div>
              <div className={`diff-cell new ${row.newText === null ? "empty" : ""}`} role="cell">
                <span className="diff-gutter" aria-hidden="true">{row.newLine ?? ""}</span>
                <span className="diff-text">{row.newText ?? ""}</span>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { useState } from "react";
import { Check, GitCompareArrows, RotateCcw, Trash2 } from "lucide-react";
import { Markdown } from "./Markdown.tsx";
import { RevisionDiff, type DiffView } from "./RevisionDiff.tsx";

export interface PendingRevision {
  id: string;
  version: number;
  content: string;
  status: string;
  createdAt: string;
  baseVersion: number;
  summary: string;
  requestedChange: string;
}

/**
 * The review gate between generation and the current draft. Nothing here
 * approves a section; acceptance only replaces the draft and marks affected
 * approvals stale.
 */
export function RevisionReview({
  sectionTitle,
  currentContent,
  candidate,
  busy,
  onAccept,
  onReject,
  onRequestAnother,
}: {
  sectionTitle: string;
  currentContent: string;
  candidate: PendingRevision;
  busy: boolean;
  onAccept: () => void;
  onReject: () => void;
  onRequestAnother: () => void;
}) {
  const [tab, setTab] = useState<"changes" | "revision">("changes");
  const [view, setView] = useState<DiffView | undefined>(undefined);

  return (
    <section className="revision-review" aria-labelledby="revision-review-title">
      <div className="revision-review-head">
        <div>
          <p className="eyebrow">Proposed revision · not applied</p>
          <h3 id="revision-review-title">Review v{candidate.version} of {sectionTitle}</h3>
        </div>
        <span className="revision-badge">v{candidate.baseVersion} → v{candidate.version}</span>
      </div>
      <p className="revision-summary">{candidate.summary || "The Architect prepared a revision for review."}</p>
      {candidate.requestedChange ? (
        <p className="meta revision-request">Requested: {candidate.requestedChange}</p>
      ) : null}
      <div className="revision-tabs" role="tablist" aria-label="Revision review view">
        <button type="button" role="tab" aria-selected={tab === "changes"} className={tab === "changes" ? "is-active" : ""} onClick={() => setTab("changes")}>
          <GitCompareArrows size={15} aria-hidden="true" /> Changes
        </button>
        <button type="button" role="tab" aria-selected={tab === "revision"} className={tab === "revision" ? "is-active" : ""} onClick={() => setTab("revision")}>
          Full revision
        </button>
      </div>
      {tab === "changes" ? (
        <RevisionDiff before={currentContent} after={candidate.content} view={view} onViewChange={setView} />
      ) : (
        <div className="reading section-reading revision-preview">
          <Markdown content={candidate.content} />
        </div>
      )}
      <p className="meta">Accepting replaces the current draft. It does not approve the section; approval stays a separate exact-version action.</p>
      <div className="actions">
        <button className="action" type="button" disabled={busy} onClick={onAccept}>
          <Check size={15} aria-hidden="true" /> Accept revision
        </button>
        <button className="action secondary" type="button" disabled={busy} onClick={onRequestAnother}>
          <RotateCcw size={15} aria-hidden="true" /> Request another revision
        </button>
        <button className="action ghost" type="button" disabled={busy} onClick={onReject}>
          <Trash2 size={15} aria-hidden="true" /> Discard
        </button>
      </div>
    </section>
  );
}

